package gameplatform.shop;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.transaction.PlatformTransactionManager;
import gameplatform.support.model.*;
class ShopIntegrationTest {
 @Configuration @EnableTransactionManagement static class Config {
  @Bean com.zaxxer.hikari.HikariDataSource ds(){var ds=new com.zaxxer.hikari.HikariDataSource();ds.setJdbcUrl("jdbc:h2:mem:shop_"+UUID.randomUUID()+";MODE=MSSQLServer;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");ds.setUsername("sa");ds.setPassword("");new ResourceDatabasePopulator(new ClassPathResource("shop-schema.sql")).execute(ds);return ds;}
  @Bean JdbcTemplate db(com.zaxxer.hikari.HikariDataSource ds){return new JdbcTemplate(ds);}
  @Bean PlatformTransactionManager tx(com.zaxxer.hikari.HikariDataSource ds){return new DataSourceTransactionManager(ds);}
  @Bean ShopService shop(JdbcTemplate db){return new ShopService(db);}
  @Bean PaymentService payment(ShopService s){return new PaymentService(s,true,"testmerchant","test-key","test-iv","https://payment-stage.ecpay.com.tw/Cashier/AioCheckOut/V5","https://callback.example","http://localhost:5173");}
 }
 AnnotationConfigApplicationContext ctx;ShopService shop;PaymentService pay;JdbcTemplate db;
 Actor buyer=new Actor(1,"MEMBER","buyer",""),friend=new Actor(2,"MEMBER","friend","");
 @BeforeEach void setup(){ctx=new AnnotationConfigApplicationContext(Config.class);shop=ctx.getBean(ShopService.class);pay=ctx.getBean(PaymentService.class);db=ctx.getBean(JdbcTemplate.class);}
 @AfterEach void close(){ctx.close();}
 Map<String,Object> pending(){shop.add(buyer,1,new ShopService.Add(1,false,null));return shop.createOrder(buyer,1,"Credit");}
 Map<String,String> result(Map<String,Object> order){var p=new HashMap<String,String>();p.put("MerchantID","testmerchant");p.put("MerchantTradeNo",order.get("orderNo").toString());p.put("TradeAmt",order.get("totalAmount").toString());p.put("TradeNo","ECPAY123");p.put("RtnCode","1");p.put("PaymentType","Credit_CreditCard");return p;}
 void sign(Map<String,String> p){p.remove("CheckMacValue");p.put("CheckMacValue",EcpayCheckMacValueUtil.generate(p,"test-key","test-iv"));}
 @Test void rejectsAnotherMemberAndStaff(){assertThrows(Problem.class,()->shop.cart(buyer,2));assertThrows(Problem.class,()->shop.orders(friend,1));assertThrows(Problem.class,()->shop.cart(new Actor(1,"ADMIN","admin",""),1));}
 @Test void cartRejectsDuplicatesOwnedAndUnreleased(){shop.add(buyer,1,new ShopService.Add(1,false,null));assertThrows(Problem.class,()->shop.add(buyer,1,new ShopService.Add(1,false,null)));assertThrows(Problem.class,()->shop.add(buyer,1,new ShopService.Add(3,false,null)));assertThrows(Problem.class,()->shop.remove(friend,2,1));}
 @Test void checkoutIsPendingAndDoesNotGrantBeforeVerifiedPayment(){var o=pending();assertEquals("PENDING",o.get("orderStatus"));assertEquals(0,shop.library(buyer,1).size());assertEquals(0,((List<?>)shop.cart(buyer,1).get("items")).size());}
 @Test void wrongSignatureAndAmountCannotGrant(){var o=pending();var p=result(o);p.put("CheckMacValue","wrong");assertThrows(Problem.class,()->pay.callback(p,false));p.put("TradeAmt","1");sign(p);assertThrows(Problem.class,()->pay.callback(p,false));assertEquals(0,shop.library(buyer,1).size());assertEquals("PENDING",shop.orderDto(((Number)o.get("orderId")).intValue()).get("orderStatus"));}
 @Test void verifiedPaymentGrantsOnceAndOnlyToBuyer(){var o=pending();var p=result(o);sign(p);assertEquals("success",pay.callback(p,false));assertEquals("success",pay.callback(p,false));assertEquals(1,shop.library(buyer,1).size());assertEquals(0,shop.library(friend,2).size());assertEquals("PAID",shop.paymentOrder(buyer,1,o.get("orderNo").toString()).get("paymentStatus"));assertThrows(Problem.class,()->shop.paymentOrder(friend,2,o.get("orderNo").toString()));}
 @Test void giftGoesToRecipientAndPaymentRollbackProtectsOtherItems(){shop.add(buyer,1,new ShopService.Add(1,true,2));var o=shop.createOrder(buyer,1,"Credit");var p=result(o);sign(p);pay.callback(p,false);assertEquals(1,shop.library(friend,2).size());assertEquals(0,shop.library(buyer,1).size());}
 @Test void couponReservesAndCancelReleases(){shop.add(buyer,1,new ShopService.Add(1,false,null));shop.apply(buyer,1,1);var o=shop.createOrder(buyer,1,"Credit");assertEquals(0,new BigDecimal("80").compareTo((BigDecimal)o.get("totalAmount")));assertEquals(1,db.queryForObject("SELECT used_count FROM coupons WHERE coupon_id=1",Integer.class));shop.cancel(buyer,1,((Number)o.get("orderId")).intValue());assertEquals(0,db.queryForObject("SELECT used_count FROM coupons WHERE coupon_id=1",Integer.class));assertThrows(Problem.class,()->shop.cancel(buyer,1,((Number)o.get("orderId")).intValue()));}
 @Test void couponMemberQuotaAndTotalLimitEnforced(){db.update("UPDATE coupons SET per_member_limit=1,total_limit=1 WHERE coupon_id=1");shop.add(buyer,1,new ShopService.Add(1,false,null));shop.apply(buyer,1,1);shop.createOrder(buyer,1,"Credit");shop.add(friend,2,new ShopService.Add(2,false,null));assertThrows(Problem.class,()->shop.apply(friend,2,1));}
 @Test void reviewsRequireOwnershipAndRemainPrivateToTheirAuthor(){assertThrows(Problem.class,()->shop.saveReview(buyer,1,1,null,new ShopService.Review(5,true,"good")));var o=pending();var p=result(o);sign(p);pay.callback(p,false);shop.saveReview(buyer,1,1,null,new ShopService.Review(5,true,"good"));int id=((Number)shop.reviews(1,buyer).getFirst().get("id")).intValue();assertEquals(true,shop.reviews(1,buyer).getFirst().get("mine"));assertEquals(false,shop.reviews(1,friend).getFirst().get("mine"));assertThrows(Problem.class,()->shop.updateReview(friend,2,id,new ShopService.Review(1,false,"bad")));shop.deleteReview(buyer,1,id);assertEquals(0,shop.reviews(1,null).size());shop.saveReview(buyer,1,1,null,new ShopService.Review(4,true,"updated"));assertEquals(1,shop.reviews(1,null).size());}
 @Test void failedAndCancelledPaymentsNeverGrant(){var o=pending();var p=result(o);p.put("RtnCode","0");sign(p);assertEquals("fail",pay.callback(p,false));assertEquals("CANCELLED",shop.orderDto(((Number)o.get("orderId")).intValue()).get("orderStatus"));p.put("RtnCode","1");sign(p);assertThrows(Problem.class,()->pay.callback(p,false));assertEquals(0,shop.library(buyer,1).size());}
 @Test void bankInfoPersistsWithoutGranting(){var o=pending();var p=result(o);p.put("RtnCode","2");p.put("BankCode","808");p.put("vAccount","123456789");p.put("ExpireDate","2026/12/31");sign(p);assertEquals("pending",pay.callback(p,true));assertEquals("123456789",shop.paymentOrder(buyer,1,o.get("orderNo").toString()).get("virtualAccount"));assertEquals(0,shop.library(buyer,1).size());}
 @Test void unconfiguredGatewayDoesNotCreateOrder(){var unconfigured=new PaymentService(shop,false,"","","","https://payment-stage.ecpay.com.tw/Cashier/AioCheckOut/V5","","http://localhost:5173");shop.add(buyer,1,new ShopService.Add(1,false,null));assertThrows(Problem.class,()->unconfigured.checkout(buyer,1,"Credit"));assertEquals(0,shop.orders(buyer,1).size());}

 @Test void concurrentCallbacksGrantExactlyOnce() throws Exception {var o=pending();var p=result(o);sign(p);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->pay.callback(p,false));var b=pool.submit(()->pay.callback(p,false));assertEquals("success",a.get(10,java.util.concurrent.TimeUnit.SECONDS));assertEquals("success",b.get(10,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(1,shop.library(buyer,1).size());}
 @Test void amountAndSnapshotConstraintsSurvivePriceChanges(){shop.add(buyer,1,new ShopService.Add(1,false,null));shop.add(buyer,1,new ShopService.Add(2,false,null));shop.apply(buyer,1,1);var o=shop.createOrder(buyer,1,"Credit");db.update("UPDATE games SET price=999 WHERE game_id=1");assertEquals(0,new BigDecimal("280").compareTo((BigDecimal)shop.orderDto(((Number)o.get("orderId")).intValue()).get("totalAmount")));var p=result(o);sign(p);pay.callback(p,false);assertEquals(2,shop.library(buyer,1).size());}
 @Test void hiddenReviewsCannotBeRestoredByAuthor(){var o=pending();var p=result(o);sign(p);pay.callback(p,false);shop.saveReview(buyer,1,1,null,new ShopService.Review(5,true,"good"));db.update("UPDATE game_reviews SET status='HIDDEN'");assertThrows(Problem.class,()->shop.saveReview(buyer,1,1,null,new ShopService.Review(5,true,"restore")));assertEquals(0,shop.reviews(1,buyer).size());}
 @Test void conflictingGameGrantRollsBackEntirePayment(){shop.add(buyer,1,new ShopService.Add(1,false,null));shop.add(buyer,1,new ShopService.Add(2,false,null));var o=shop.createOrder(buyer,1,"Credit");db.update("INSERT INTO member_games(member_id,game_id,obtained_source) VALUES(1,2,'ADMIN')");var p=result(o);sign(p);assertThrows(Problem.class,()->pay.callback(p,false));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM member_games WHERE member_id=1 AND game_id=1",Integer.class));assertEquals("PENDING",shop.orderDto(((Number)o.get("orderId")).intValue()).get("orderStatus"));}
 @Test void differentGatewayTradeCannotReplacePaidTrade(){var o=pending();var p=result(o);sign(p);pay.callback(p,false);p.put("TradeNo","another-trade");sign(p);assertThrows(Problem.class,()->pay.callback(p,false));assertEquals(1,shop.library(buyer,1).size());}
 @Test void wrongMerchantAndPendingDuplicateRejectWithoutSideEffects(){var o=pending();var p=result(o);p.put("MerchantID","another");sign(p);assertThrows(Problem.class,()->pay.callback(p,false));shop.add(buyer,1,new ShopService.Add(1,false,null));assertThrows(Problem.class,()->shop.createOrder(buyer,1,"Credit"));assertEquals(1,shop.orders(buyer,1).size());}
 @Test void signedCheckoutOnlyReturnsPendingGatewayForm(){shop.add(buyer,1,new ShopService.Add(1,false,null));var form=pay.checkout(buyer,1,"ATM");assertEquals("https://payment-stage.ecpay.com.tw/Cashier/AioCheckOut/V5",form.get("actionUrl"));assertEquals(0,shop.library(buyer,1).size());assertEquals(1,shop.orders(buyer,1).size());}

 @Test void allocatedDiscountMatchesOrderTotalWithFreeLastItem(){db.update("INSERT INTO games VALUES(4,'Free item',NULL,0,'PUBLISHED')");db.update("UPDATE games SET price=101 WHERE game_id=1");for(int game:List.of(1,2,4))shop.add(buyer,1,new ShopService.Add(game,false,null));shop.apply(buyer,1,1);var o=shop.createOrder(buyer,1,"Credit");BigDecimal sum=db.queryForObject("SELECT SUM(discount_amount) FROM order_items WHERE order_id=?",BigDecimal.class,o.get("orderId"));assertEquals(0,new BigDecimal("20").compareTo(sum));assertEquals(0,new BigDecimal("281").compareTo((BigDecimal)o.get("totalAmount")));}
}
